import {getApiErrorMessage} from "../../api/errors";
import QueryError from "../shared/QueryError";
import React, {useEffect, useState} from "react";
import {GridRowId, GridRowSelectionModel} from "@mui/x-data-grid";
import {Box, Button, Checkbox, Chip, Dialog, DialogActions, DialogContent, DialogContentText, DialogTitle, IconButton, InputAdornment, InputLabel, LinearProgress, Paper, Stack, TablePagination, TextField, Typography, useMediaQuery} from "@mui/material";
import AddIcon from "@mui/icons-material/Add";
import ClearIcon from "@mui/icons-material/Clear";
import FilterAltOutlinedIcon from "@mui/icons-material/FilterAltOutlined";
import DeleteOutlineIcon from "@mui/icons-material/DeleteOutline";
import SearchRoundedIcon from "@mui/icons-material/SearchRounded";
import {NavLink} from "react-router-dom";
import styledCom from "styled-components";
import Loader from "../../ui/loader/loader";
import CoreButton from "../../ui/buttons/coreButton";
import {
    MainDiv,
    PageHeader,
    PageSubtitle,
    PageTitle,
    PageTitleGroup,
    StyledDataGrid,
    Surface,
    Toolbar,
    ToolbarActions,
} from "../../ui/commonStyled/commonStyled";
import productColumns, {ProductActions, ProductPricing} from "./productColumns";
import {isProductPricingInactive} from "./productPricing";
import {ProductParams} from "../../models/product";
import useDebounce from "../../hooks/useDebounce";
import {
    useBulkDeleteProductsMutation,
    useDeleteProductMutation,
    useGetProductsQuery,
} from "./productsApi";
import {useTranslation} from "../../i18n";
import {CategoryType} from "../../models/category";
import {useGetLastLevelCategoriesQuery} from "../categories/categoriesApi";
import CoreFormControl from "../../ui/formControl/coreFormControl";
import CoreSelect from "../../ui/select/coreSelect";
import BulkDeleteDialog from "../shared/bulkDelete/BulkDeleteDialog";
import {toast} from "react-toastify";

const SearchLabel = styledCom.div({
    display: "flex",
    alignItems: "center",
    gap: "8px",
    color: "var(--color-muted)",
    fontSize: "13px",
    fontWeight: 700,
});
const ProductFilters = styledCom.div({
    display: "grid",
    gridTemplateColumns: "minmax(0, 1fr) minmax(0, 0.6fr) auto",
    gap: "14px",
    alignItems: "end",
    "@media (max-width: 820px)": {gridTemplateColumns: "1fr"},
});

const initialProductParams: ProductParams = {
    pageNumber: 1,
    pageSize: 25,
    productCategories: [],
    searchTerm: "",
};

const ProductsManagement = () => {
    const {t, locale} = useTranslation();
    const mobile = useMediaQuery("(max-width:700px)");
    const [productParams, setProductParams] = useState<ProductParams>(initialProductParams);
    const {data, isLoading, isFetching, isError, error, refetch} = useGetProductsQuery(productParams);
    const {data: categories = []} = useGetLastLevelCategoriesQuery({type: CategoryType.Product});
    const [deleteProduct, {isLoading: isDeleting}] = useDeleteProductMutation({});
    const [bulkDeleteProducts, {isLoading: isBulkDeleting}] = useBulkDeleteProductsMutation();

    const [searchTerm, setSearchTerm] = useState("");
    const debouncedSearch = useDebounce(searchTerm);

    const [deleteWindowOpen, setDeleteWindowOpen] = useState(false);
    const [deletedId, setDeletedId] = useState<GridRowId>("");
    const [selectedIds, setSelectedIds] = useState<GridRowSelectionModel>([]);
    const [bulkDeleteOpen, setBulkDeleteOpen] = useState(false);
    const [paginationModel, setPaginationModel] = useState({page: 0, pageSize: initialProductParams.pageSize});
    const categoryOptions = [
        {id: "", name: t("All categories")},
        ...categories.map((category) => ({id: category.name, name: category.name})),
    ];

    const handleSetProduct = (id: GridRowId) => {
        setDeleteWindowOpen(true);
        setDeletedId(id);
    };

    async function deleteProductHandler() {
        try {
            await deleteProduct(deletedId).unwrap();
            toast.success(t("Продукт удалён."));
            setSelectedIds((current) => current.filter((id) => id !== deletedId));
            setDeleteWindowOpen(false);
        } catch (failure) {
            toast.error(getApiErrorMessage(failure, t("Не удалось удалить запись.")));
        }
    }

    useEffect(() => {
        setProductParams((current) => ({...current, searchTerm: debouncedSearch, pageNumber: 1}));
        setPaginationModel((current) => ({...current, page: 0}));
    }, [debouncedSearch]);

    const pageChangeHandler = (e: any) => {
        setProductParams((current) => ({
            ...current,
            pageNumber: e.page + 1,
            pageSize: e.pageSize,
        }));
        setPaginationModel(e);
    };

    const bulkDeleteHandler = async () => {
        try {
            const result = await bulkDeleteProducts({ids: selectedIds.map(Number)}).unwrap();
            setSelectedIds([]);
            setBulkDeleteOpen(false);
            toast.success(t("Deleted items: {count}", {count: result.deleted}));
        } catch (failure) {
            toast.error(getApiErrorMessage(failure, t("Не удалось удалить запись.")));
        }
    };

    if (isLoading && !searchTerm) {
        return <Loader/>;
    }

    if (isError) return <MainDiv><QueryError error={error} onRetry={refetch}/></MainDiv>;

    return (
        <MainDiv>
            <BulkDeleteDialog
                open={bulkDeleteOpen}
                selectedCount={selectedIds.length}
                isLoading={isBulkDeleting}
                onClose={() => setBulkDeleteOpen(false)}
                onConfirm={bulkDeleteHandler}
            />
            <Dialog
                open={deleteWindowOpen}
                onClose={() => {if (!isDeleting) setDeleteWindowOpen(false);}}
            >
                <DialogTitle>{t("Подтверждение удаления продукта")}</DialogTitle>
                <DialogContent>
                    <DialogContentText>
                        {t("Вы действительно хотите удалить этот продукт из системы?")}
                    </DialogContentText>
                </DialogContent>
                <DialogActions>
                    <Button disabled={isDeleting} onClick={() => setDeleteWindowOpen(false)}>{t("Отмена")}</Button>
                    <Button color="error" disabled={isDeleting} onClick={() => void deleteProductHandler()} autoFocus>
                        {t("Удалить")}
                    </Button>
                </DialogActions>
            </Dialog>

            <PageHeader>
                <PageTitleGroup>
                    <PageTitle>{t("Продукты")}</PageTitle>
                    <PageSubtitle>
                        {t("Каталог товаров с ценами, категориями, быстрым поиском и действиями.")}
                    </PageSubtitle>
                </PageTitleGroup>
                <NavLink to="createProduct" style={{textDecoration: "none"}}>
                    <CoreButton
                        muiType="success"
                        text={t("Добавить продукт")}
                        leftIcon={<AddIcon/>}
                    />
                </NavLink>
            </PageHeader>

            <Surface>
                <Toolbar>
                    <SearchLabel>
                        <FilterAltOutlinedIcon fontSize="small"/>
                        {t("Catalog filters")}
                        <Chip size="small" color="primary" label={t("Found: {count}", {count: data?.metaData.totalCount ?? 0})}/>
                    </SearchLabel>
                    <ToolbarActions>
                        {selectedIds.length > 0 && (
                            <CoreButton
                                muiType="secondary"
                                text={t("Clear selection")}
                                leftIcon={<ClearIcon/>}
                                onClick={() => setSelectedIds([])}
                            />
                        )}
                        {selectedIds.length > 0 && <CoreButton
                            muiType="error"
                            text={t("Delete selected ({count})", {count: selectedIds.length})}
                            leftIcon={<DeleteOutlineIcon/>}
                            disabled={selectedIds.length === 0 || isBulkDeleting}
                            onClick={() => setBulkDeleteOpen(true)}
                        />}
                    </ToolbarActions>
                </Toolbar>
                <ProductFilters>
                    <TextField
                        size="small"
                        value={searchTerm || ""}
                        label={t("Название товара или описание...")}
                        onChange={(e: any) => setSearchTerm(e.target.value)}
                        InputProps={{startAdornment: <InputAdornment position="start"><SearchRoundedIcon fontSize="small"/></InputAdornment>, endAdornment: searchTerm ? <InputAdornment position="end"><IconButton size="small" aria-label="Очистить поиск товаров" onClick={() => setSearchTerm("")}><ClearIcon fontSize="small"/></IconButton></InputAdornment> : undefined}}
                    />
                    <CoreFormControl>
                        <InputLabel>{t("Category")}</InputLabel>
                        <CoreSelect
                            required={false}
                            value={productParams.categories ?? ""}
                            label={t("Category")}
                            menuItemProps={categoryOptions}
                            onChange={(event: any) => {
                                setProductParams((current) => ({
                                    ...current,
                                    categories: String(event.target.value) || undefined,
                                    pageNumber: 1,
                                }));
                                setPaginationModel((current) => ({...current, page: 0}));
                            }}
                        />
                    </CoreFormControl>
                    <CoreButton
                        muiType="secondary"
                        text={t("Reset filters")}
                        leftIcon={<ClearIcon/>}
                        disabled={!searchTerm && !productParams.categories}
                        onClick={() => {
                            setSearchTerm("");
                            setProductParams({...initialProductParams});
                            setPaginationModel({page: 0, pageSize: initialProductParams.pageSize});
                        }}
                    />
                </ProductFilters>
                {mobile ? <Box sx={{mt: 2.5}}>
                    {isFetching && <LinearProgress aria-label="Обновление каталога"/>}
                    <Stack spacing={1.5}>
                        {!data?.items.length && <Typography color="text.secondary">Товары не найдены. Измените поиск или сбросьте фильтры.</Typography>}
                        {data?.items.map(product => <Paper key={product.id} variant="outlined" sx={{p: 1.5, minWidth: 0}}>
                            <Stack direction="row" alignItems="flex-start" gap={1}>
                                <Checkbox size="small" checked={selectedIds.includes(product.id)} inputProps={{"aria-label": `Выбрать товар: ${product.name}`}} onChange={(_, checked) => setSelectedIds(current => checked ? [...current, product.id] : current.filter(id => id !== product.id))}/>
                                <Box sx={{flex: 1, minWidth: 0}}><Typography component={NavLink} to={`/productsManagement/editProduct/productDetails/${product.id}`} sx={{fontWeight: 700, color: "text.primary", textDecoration: "none", overflowWrap: "anywhere"}}>{product.name}</Typography>
                                    <Typography variant="caption" display="block" color="text.secondary">{product.category || "Без категории"}{product.gtin ? ` · ${product.gtin}` : ""}</Typography>
                                </Box>
                                <ProductActions id={product.id} name={product.name} onDelete={handleSetProduct} t={t}/>
                            </Stack>
                            <ProductPricing product={product} locale={locale}/>
                            <Chip size="small" color={isProductPricingInactive(product) ? "warning" : "success"} label={isProductPricingInactive(product) ? "Неактивна: заполните цены" : "Активна"}/>
                        </Paper>)}
                    </Stack>
                    <TablePagination component="div" count={data?.metaData.totalCount ?? 0} page={paginationModel.page} rowsPerPage={paginationModel.pageSize} rowsPerPageOptions={[25, 50, 100]} labelRowsPerPage="На странице" labelDisplayedRows={({from, to, count}) => `${from}–${to} из ${count}`} onPageChange={(_, page) => pageChangeHandler({...paginationModel, page})} onRowsPerPageChange={event => pageChangeHandler({page: 0, pageSize: Number(event.target.value)})}/>
                </Box> : <StyledDataGrid
                    sx={{mt: 2.5}}
                    pagination
                    paginationMode="server"
                    rowCount={data?.metaData.totalCount ?? 0}
                    autoHeight
                    rowHeight={112}
                    rows={data?.items ?? []}
                    columns={productColumns(handleSetProduct, t, locale)}
                    loading={isLoading || isFetching}
                    onPaginationModelChange={(e) => pageChangeHandler(e)}
                    paginationModel={paginationModel}
                    pageSizeOptions={[25, 50, 100]}
                    disableRowSelectionOnClick
                    checkboxSelection
                    keepNonExistentRowsSelected
                    rowSelectionModel={selectedIds}
                    onRowSelectionModelChange={setSelectedIds}
                />}
            </Surface>
        </MainDiv>
    );
};

export default ProductsManagement;
