import {GridColDef, GridRowId} from "@mui/x-data-grid";
import {NavLink} from "react-router-dom";
import ContentCopyOutlinedIcon from "@mui/icons-material/ContentCopyOutlined";
import EditOutlinedIcon from "@mui/icons-material/EditOutlined";
import DeleteOutlineRoundedIcon from "@mui/icons-material/DeleteOutlineRounded";
import VisibilityOutlinedIcon from "@mui/icons-material/VisibilityOutlined";
import MoreHorizRoundedIcon from "@mui/icons-material/MoreHorizRounded";
import React, {useState} from "react";
import {Avatar, Box, Chip, IconButton, ListItemIcon, Menu, MenuItem, Tooltip} from "@mui/material";
import {getCurrentLanguage, Translate} from "../../i18n";
import {getLanguageOption} from "../../i18n/translations";
import {isProductPricingInactive} from "./productPricing";

export function ProductActions({id, name, onDelete, t}: {id: GridRowId; name: string; onDelete: (id: GridRowId) => void; t: Translate}) {
    const [anchor, setAnchor] = useState<HTMLElement | null>(null);
    return <Box sx={{display: "flex", gap: .5}}>
        <Tooltip title={t("Подробнее")}><IconButton size="small" component={NavLink} to={`/productsManagement/editProduct/productDetails/${id}`} aria-label={`${t("Подробнее")}: ${name}`}><VisibilityOutlinedIcon fontSize="small"/></IconButton></Tooltip>
        <Tooltip title={t("Actions")}><IconButton size="small" aria-label={`${t("Actions")}: ${name}`} aria-haspopup="menu" aria-expanded={Boolean(anchor)} onClick={event => setAnchor(event.currentTarget)}><MoreHorizRoundedIcon fontSize="small"/></IconButton></Tooltip>
        <Menu anchorEl={anchor} open={Boolean(anchor)} onClose={() => setAnchor(null)}>
            <MenuItem component={NavLink} to={`/productsManagement/editProduct/${id}`} onClick={() => setAnchor(null)}><ListItemIcon><EditOutlinedIcon fontSize="small"/></ListItemIcon>{t("Редактировать")}</MenuItem>
            <MenuItem component={NavLink} to={`/productsManagement/copyProduct/${id}`} onClick={() => setAnchor(null)}><ListItemIcon><ContentCopyOutlinedIcon fontSize="small"/></ListItemIcon>{t("Скопировать")}</MenuItem>
            <MenuItem sx={{color: "error.main"}} onClick={() => {setAnchor(null); onDelete(id);}}><ListItemIcon sx={{color: "inherit"}}><DeleteOutlineRoundedIcon fontSize="small"/></ListItemIcon>{t("Удалить")}</MenuItem>
        </Menu>
    </Box>;
}

export function ProductPricing({product, locale}: {product: {price?: number; purchasePrice?: number | null; costPrice?: number | null; markupPercent?: number | null}; locale: string}) {
    const money = (value: number | null | undefined) => value == null || value <= 0 ? "Не указана" : value.toLocaleString(locale, {maximumFractionDigits: 6});
    return <Box sx={{py: 1, lineHeight: 1.5, fontVariantNumeric: "tabular-nums"}}>
        <Box sx={{fontSize: 11, color: "text.secondary"}}>Конечная цена</Box>
        <Box component="strong" sx={{display: "block", fontSize: 15}}>{product.price && product.price > 0 ? `${product.price.toLocaleString(locale, {minimumFractionDigits: 2, maximumFractionDigits: 2})} BYN` : "Цена не указана"}</Box>
        <Box sx={{fontSize: 12, color: "text.secondary"}}>Закупочная цена: {money(product.purchasePrice)}</Box>
        <Box sx={{fontSize: 12, color: "text.secondary"}}>Себестоимость: {money(product.costPrice)}</Box>
        <Box sx={{fontSize: 12, color: "text.secondary"}}>Надбавка: {product.markupPercent == null ? "Не указана" : `${product.markupPercent.toLocaleString(locale)} %`}</Box>
    </Box>;
}

const productColumns = (handleSetProduct: (id: GridRowId) => void, t: Translate, locale = getLanguageOption(getCurrentLanguage()).locale): GridColDef[] => [
    {field: "imageName", align: "center", headerName: "", width: 56, sortable: false,
        renderCell: params => <Avatar sx={{width: 36, height: 36, borderRadius: "10px", bgcolor: "primary.light", color: "primary.main", fontSize: 14, fontWeight: 700}} variant="rounded" src={params.value} alt={params.row.name}>{String(params.row.name || "").slice(0, 1)}</Avatar>},
    {field: "name", headerName: t("Название"), minWidth: 220, flex: 1, renderCell: params => <Box component={NavLink} to={`/productsManagement/editProduct/productDetails/${params.id}`} sx={{fontWeight: 650, color: "text.primary", textDecoration: "none", "&:hover": {color: "primary.main"}}}>{params.value}</Box>},
    {field: "price", headerName: "Цены, BYN", description: "Конечная цена, закупочная цена, себестоимость и надбавка", type: "number", align: "left", headerAlign: "left", width: 220,
        renderCell: params => <ProductPricing product={params.row} locale={locale}/>},
    {field: "requiresPriceApproval", headerName: "Статус карточки", width: 150, renderCell: params => {
        const inactive = isProductPricingInactive(params.row);
        return <Tooltip title={inactive ? "Заполните закупочную цену, себестоимость, надбавку и конечную цену; утверждённые цены должны быть подтверждены" : "Карточка доступна для заказов"}><Chip size="small" color={inactive ? "warning" : "success"} label={inactive ? "Неактивна: цены" : "Активна"}/></Tooltip>;
    }},
    {field: "gtin", headerName: "GTIN", minWidth: 136, flex: .55},
    {field: "category", headerName: t("Категория"), minWidth: 144, flex: .6,
        renderCell: params => params.value ? <Chip size="small" label={params.value} sx={{bgcolor: "action.hover", color: "text.secondary"}}/> : "—"},
    {field: "actions", headerName: t("Actions"), width: 92, align: "right", headerAlign: "right", sortable: false, filterable: false, disableColumnMenu: true,
        renderCell: params => <ProductActions id={params.id} name={params.row.name} onDelete={handleSetProduct} t={t}/>},
];

export default productColumns;
