import React, {ReactNode} from "react";
import {MySelect} from "./styled";
import {MenuItem} from "@mui/material";

interface CoreSelectProps {
    id?: string;
    labelId?: string;
    value?: any;
    onChange?: any;
    label: ReactNode;
    menuItemProps?: any[];
    name?: string;
    register?: any;
    error?: any;
    required?: boolean;
    disabled?: boolean;
    defaultValue?: any;
    withoutId?: boolean;
}

const CoreSelect = ({
                        id,
                        labelId,
                        value,
                        onChange,
                        label,
                        menuItemProps,
                        register,
                        name,
                        error,
                        required,
                        defaultValue,
                        disabled,
                        withoutId
                    }: CoreSelectProps) => {

    if (register && withoutId) {
        return (
            <MySelect
                id={id}
                labelId={labelId}
                displayEmpty
                defaultValue={defaultValue}
                disabled={disabled}
                required={required}
                error={!!error}
                {...register(name)}
                value={value}
                onChange={onChange}
                label={label}
            >
                {menuItemProps &&
                    menuItemProps.map((menuItem) => {
                        return <MenuItem
                            key={String(menuItem)}
                            value={menuItem}>
                            {menuItem}
                        </MenuItem>;
                    })}
            </MySelect>

        );
    }

    if (register) {
        return (
            <MySelect
                id={id}
                labelId={labelId}
                displayEmpty
                defaultValue={defaultValue}
                disabled={disabled}
                required={required}
                error={!!error}
                {...register(name)}
                value={value}
                onChange={onChange}
                label={label}
            >
                {menuItemProps &&
                    menuItemProps.map((menuItem) => {
                        return <MenuItem key={menuItem.id}
                                         value={menuItem.id}>
                            {menuItem.name}
                        </MenuItem>;
                    })}
            </MySelect>

        );
    }

    return (
        <MySelect id={id} labelId={labelId} value={value} onChange={onChange} label={label} required={required !== false} disabled={disabled} error={!!error}>
            {menuItemProps &&
                menuItemProps.map((menuItem) => {
                    return <MenuItem key={menuItem.id} value={menuItem.id}>{menuItem.name}</MenuItem>;
                })}
        </MySelect>
    );
};

export default CoreSelect;
